@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Outfit:wght@500;600;700&display=swap');

:root {
  --primary: #00824A;
  --dark: #32462F;
  --cream: #F3CEA1;
  --bg-color: #FDF9F5;
  --text-main: #1E2922;
  --text-muted: #5B6B5D;
  --border-color: #E2E8F0;
  --white: #FFFFFF;
  --shadow-sm: 0 4px 6px rgba(0, 0, 0, 0.04);
  --shadow-md: 0 10px 15px -3px rgba(0, 0, 0, 0.08);
  --shadow-lg: 0 20px 25px -5px rgba(0, 0, 0, 0.1);
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-full: 9999px;
  --transition: all 0.25s ease;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
  font-family: 'Inter', sans-serif;
  color: var(--text-main);
  background-color: var(--bg-color);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Outfit', sans-serif;
  color: var(--dark);
  font-weight: 700;
  line-height: 1.2;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover { color: var(--dark); }

img { max-width: 100%; height: auto; display: block; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 1rem;
  cursor: pointer;
  transition: var(--transition);
  border: 2px solid transparent;
  text-align: center;
}

.btn-primary {
  background-color: var(--primary);
  color: var(--white);
}

.btn-primary:hover {
  background-color: var(--dark);
  color: var(--white);
}

.btn-outline {
  background-color: transparent;
  border-color: var(--primary);
  color: var(--primary);
}

.btn-outline:hover {
  background-color: var(--primary);
  color: var(--white);
}

/* Header & Nav */
.header {
  background-color: var(--white);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 1000;
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 1rem 1.5rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: 'Outfit', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo span {
  color: var(--dark);
}

.nav-links {
  display: flex;
  gap: 2rem;
  align-items: center;
}

.nav-links a {
  color: var(--text-main);
  font-weight: 500;
}

.nav-links a:hover, .nav-links a.active {
  color: var(--primary);
}

.nav-actions {
  display: flex;
  gap: 1rem;
  align-items: center;
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  font-size: 1.5rem;
  cursor: pointer;
  color: var(--dark);
}

/* Global Container */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Sections */
.section {
  padding: 5rem 0;
}

.section-title {
  font-size: 2.5rem;
  margin-bottom: 3rem;
  text-align: center;
}

/* Hero Section */
.hero {
  background-color: var(--cream);
  padding: 6rem 1.5rem;
  text-align: center;
  border-radius: var(--radius-lg);
  margin: 2rem auto;
  max-width: 1200px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
}

.hero h1 {
  font-size: 4rem;
  color: var(--dark);
}

.hero p {
  font-size: 1.25rem;
  color: var(--text-muted);
  max-width: 600px;
}

/* Cards (Promos, Highlights) */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

.promo-card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.promo-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-5px);
}

.promo-image {
  width: 100%;
  height: 250px;
  background-color: var(--cream);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  color: var(--primary);
}

.promo-content {
  padding: 2rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.promo-content h3 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.promo-content p {
  color: var(--text-muted);
  margin-bottom: 2rem;
  flex-grow: 1;
}

/* Menu Page Layout */
.menu-layout {
  display: grid;
  grid-template-columns: 250px 1fr;
  gap: 3rem;
  padding: 3rem 0;
}

.menu-sidebar {
  position: sticky;
  top: 100px;
  align-self: start;
}

.menu-sidebar h3 {
  margin-bottom: 1rem;
  font-size: 1.25rem;
}

.menu-sidebar ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.menu-sidebar a {
  color: var(--text-muted);
  display: block;
  padding: 0.5rem 0;
}

.menu-sidebar a:hover, .menu-sidebar a.active {
  color: var(--primary);
  font-weight: 600;
}

.menu-section {
  margin-bottom: 4rem;
}

.menu-section-title {
  font-size: 2rem;
  margin-bottom: 2rem;
  padding-bottom: 1rem;
  border-bottom: 2px solid var(--border-color);
}

.menu-items-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 1.5rem;
}

.menu-item {
  text-align: center;
}

.menu-item-img {
  width: 140px;
  height: 140px;
  border-radius: 50%;
  background-color: #E2E8F0;
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
}

.menu-item h4 {
  font-size: 1.1rem;
}

/* Rewards Page */
.rewards-hero {
  background-color: var(--dark);
  color: var(--white);
  padding: 5rem 1.5rem;
  text-align: center;
  margin-bottom: 4rem;
}

.rewards-hero h1 { color: var(--white); font-size: 3rem; margin-bottom: 1rem;}
.rewards-hero p { font-size: 1.2rem; margin-bottom: 2rem; }

.tiers-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.tier-card {
  background: var(--white);
  padding: 2.5rem;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  text-align: center;
}

.tier-icon { font-size: 3rem; margin-bottom: 1rem; color: var(--primary); }
.tier-card h3 { font-size: 1.5rem; margin-bottom: 0.5rem; }
.tier-threshold { font-weight: 600; color: var(--primary); margin-bottom: 1.5rem; display: block; }
.tier-card ul { list-style: none; text-align: left; }
.tier-card li { margin-bottom: 0.75rem; padding-left: 1.5rem; position: relative; }
.tier-card li::before {
  content: '★';
  color: var(--primary);
  position: absolute;
  left: 0;
  top: 0;
}

/* Rewards Redemption Tabs */
.redemption-section {
  background-color: #EBF3F0;
  padding: 4rem 0;
  margin: 4rem 0;
}

.tabs-header {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
  flex-wrap: wrap;
}

.tab-btn {
  background: transparent;
  border: none;
  font-size: 1.5rem;
  font-family: var(--font-heading);
  font-weight: 700;
  color: var(--text-muted);
  cursor: pointer;
  padding: 0.5rem 1rem;
  border-bottom: 4px solid transparent;
  transition: var(--transition);
}

.tab-btn.active {
  color: var(--dark);
  border-bottom-color: var(--primary);
}

.tab-content {
  display: none;
  text-align: center;
  max-width: 600px;
  margin: 0 auto;
}

.tab-content.active {
  display: block;
  animation: fadeIn 0.4s ease;
}

.tab-content h3 { font-size: 2rem; margin-bottom: 1rem; }
.tab-content p { font-size: 1.1rem; color: var(--text-muted); }

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Gift Cards Page */
.gift-hero {
  padding: 4rem 0;
  text-align: center;
}

.gift-carousel-container {
  position: relative;
  margin-bottom: 4rem;
  overflow: hidden;
  padding: 0 3rem;
}

.carousel-title { margin-bottom: 1.5rem; font-size: 1.5rem; }

.carousel-track {
  display: flex;
  gap: 1.5rem;
  transition: transform 0.4s ease;
}

.gift-card-item {
  flex: 0 0 250px;
  height: 160px;
  background-color: var(--cream);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
  font-weight: 600;
  color: var(--dark);
  text-align: center;
  padding: 1rem;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: var(--white);
  border: 1px solid var(--border-color);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  cursor: pointer;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
}

.carousel-btn.prev { left: 0; }
.carousel-btn.next { right: 0; }
.carousel-btn:hover { background: var(--primary); color: var(--white); border-color: var(--primary); }

/* Store Locator Page */
.locator-layout {
  display: grid;
  grid-template-columns: 350px 1fr;
  height: calc(100vh - 80px); /* 80px is header approx */
}

.locator-sidebar {
  background: var(--white);
  border-right: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
}

.locator-search {
  padding: 1.5rem;
  border-bottom: 1px solid var(--border-color);
}

.search-controls {
  display: flex;
  gap: 0.5rem;
  margin-top: 1rem;
}

.search-input {
  flex-grow: 1;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
}

.toggle-group {
  display: flex;
  background: #E2E8F0;
  border-radius: var(--radius-full);
  padding: 0.25rem;
  margin-top: 1rem;
}

.toggle-btn {
  flex: 1;
  padding: 0.5rem;
  text-align: center;
  border: none;
  background: transparent;
  border-radius: var(--radius-full);
  cursor: pointer;
  font-weight: 500;
}

.toggle-btn.active {
  background: var(--white);
  box-shadow: var(--shadow-sm);
}

.store-list {
  flex-grow: 1;
  overflow-y: auto;
  padding: 1rem 0;
}

.store-item {
  padding: 1.5rem;
  border-bottom: 1px solid var(--border-color);
  cursor: pointer;
}

.store-item:hover {
  background-color: #F8FAFC;
}

.store-item h4 { margin-bottom: 0.5rem; }
.store-item p { color: var(--text-muted); font-size: 0.9rem; margin-bottom: 0.5rem; }

.locator-map {
  background-color: #E2E8F0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  font-size: 1.5rem;
}

/* Footer */
.footer {
  background-color: var(--white);
  padding: 4rem 1.5rem 2rem;
  border-top: 1px solid var(--border-color);
  margin-top: 4rem;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 3rem;
  margin-bottom: 3rem;
}

.footer-col h4 {
  font-size: 1.1rem;
  margin-bottom: 1.5rem;
  cursor: default;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 0.75rem;
}

.footer-col a {
  color: var(--text-muted);
}

.footer-col a:hover {
  color: var(--primary);
}

.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 2rem;
  border-top: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.social-links {
  display: flex;
  gap: 1rem;
}

.social-links a {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--dark);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: var(--dark);
  color: var(--white);
  padding: 1.5rem;
  z-index: 2000;
  display: flex;
  justify-content: space-between;
  align-items: center;
  box-shadow: 0 -4px 6px rgba(0,0,0,0.1);
}

.cookie-content {
  flex-grow: 1;
  margin-right: 2rem;
}

.cookie-content h4 {
  color: var(--white);
  margin-bottom: 0.5rem;
}

.cookie-actions {
  display: flex;
  gap: 1rem;
}

/* Responsive */
@media (max-width: 768px) {
  .nav-links, .nav-actions {
    display: none; /* simple mobile hide for now */
  }
  .mobile-menu-btn { display: block; }
  .hero h1 { font-size: 2.5rem; }

  .menu-layout {
    grid-template-columns: 1fr;
  }
  .menu-sidebar { position: static; }

  .tiers-grid { grid-template-columns: 1fr; }

  .locator-layout { grid-template-columns: 1fr; height: auto; display: flex; flex-direction: column;}
  .locator-map { height: 400px; order: -1; }

  .footer-col h4 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
  }
  .footer-col h4::after {
    content: '+';
    font-size: 1.5rem;
    font-weight: 400;
  }
  .footer-col.expanded h4::after { content: '-'; }
  .footer-col ul { display: none; padding-top: 1rem; }
  .footer-col.expanded ul { display: block; }

  .cookie-banner {
    flex-direction: column;
    gap: 1.5rem;
  }
  .cookie-content { margin-right: 0; text-align: center; }
  .cookie-actions { width: 100%; justify-content: stretch; }
  .cookie-actions .btn { flex: 1; }
}

document.addEventListener('DOMContentLoaded', () => {
  // Cookie Banner
  const cookieBanner = document.getElementById('cookie-banner');
  const cookieAgreeBtn = document.getElementById('cookie-agree-btn');

  if (cookieBanner && cookieAgreeBtn) {
    if(!localStorage.getItem('cookies-agreed')) {
      cookieBanner.style.display = 'flex';
    } else {
      cookieBanner.style.display = 'none';
    }

    cookieAgreeBtn.addEventListener('click', () => {
      cookieBanner.style.display = 'none';
      localStorage.setItem('cookies-agreed', 'true');
    });
  }

  // Mobile Footer Accordion
  const footerCols = document.querySelectorAll('.footer-col h4');
  if (window.innerWidth <= 768) {
    footerCols.forEach(col => {
      col.addEventListener('click', () => {
        const parent = col.parentElement;
        parent.classList.toggle('expanded');
      });
    });
  }

  // Rewards Tabs
  const tabBtns = document.querySelectorAll('.tab-btn');
  const tabContents = document.querySelectorAll('.tab-content');

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      // Remove active from all
      tabBtns.forEach(b => b.classList.remove('active'));
      tabContents.forEach(c => c.classList.remove('active'));

      // Add active to current
      btn.classList.add('active');
      const targetId = btn.getAttribute('data-target');
      document.getElementById(targetId).classList.add('active');
    });
  });

  // Gift Card Carousels
  const carousels = document.querySelectorAll('.gift-carousel-container');
  carousels.forEach(carousel => {
    const track = carousel.querySelector('.carousel-track');
    const prevBtn = carousel.querySelector('.prev');
    const nextBtn = carousel.querySelector('.next');
    if(track && prevBtn && nextBtn) {
      let scrollPos = 0;
      const itemWidth = 274; // 250px + 24px gap

      nextBtn.addEventListener('click', () => {
        const maxScroll = track.scrollWidth - track.clientWidth;
        scrollPos = Math.min(scrollPos + itemWidth * 2, maxScroll);
        track.style.transform = `translateX(-${scrollPos}px)`;
      });

      prevBtn.addEventListener('click', () => {
        scrollPos = Math.max(scrollPos - itemWidth * 2, 0);
        track.style.transform = `translateX(-${scrollPos}px)`;
      });
    }
  });

  // Store Locator Interactivity
  const searchInput = document.getElementById('store-search');
  const storeList = document.getElementById('store-results-list');
  const orderTypeBtns = document.querySelectorAll('.toggle-btn');
  const filterBtn = document.getElementById('filter-btn');

  // Dummy stores
  const dummyStores = [
    { name: 'Surry Hills', address: '123 Espresso St, Surry Hills NSW 2010', type: 'pickup' },
    { name: 'Sydney CBD', address: '45 George St, Sydney NSW 2000', type: 'both' },
    { name: 'Bondi Junction', address: 'Westfield Bondi, NSW 2022', type: 'delivery' }
  ];

  if (storeList) {
    let currentType = 'pickup';

    const renderStores = (query = '') => {
      storeList.innerHTML = '';
      const filtered = dummyStores.filter(store => {
        const matchesQuery = store.name.toLowerCase().includes(query.toLowerCase()) || store.address.toLowerCase().includes(query.toLowerCase());
        const matchesType = store.type === 'both' || store.type === currentType;
        return matchesQuery && matchesType;
      });

      if(filtered.length === 0) {
        storeList.innerHTML = '<div class="store-item"><p>No stores found matching your criteria.</p></div>';
        return;
      }

      filtered.forEach(store => {
        const div = document.createElement('div');
        div.className = 'store-item';
        div.innerHTML = `<h4>GreenBean ${store.name}</h4><p>${store.address}</p><p>Hours: 6:00 AM - 6:00 PM</p>`;
        storeList.appendChild(div);
      });
    };

    renderStores();

    if(searchInput) {
      searchInput.addEventListener('input', (e) => {
        renderStores(e.target.value);
      });
    }

    orderTypeBtns.forEach(btn => {
      btn.addEventListener('click', (e) => {
        orderTypeBtns.forEach(b => b.classList.remove('active'));
        e.target.classList.add('active');
        currentType = e.target.getAttribute('data-type');
        renderStores(searchInput ? searchInput.value : '');
      });
    });

    if(filterBtn) {
      filterBtn.addEventListener('click', () => {
        alert('Filter options panel opened (prototype).');
      });
    }
  }
});

